-- load_order_staging.sql
-- Generated by scripts/make_wwi_jobs.py: edit WWI_JOBS there and rerun it, rather than editing this file.
-- Fills WideWorldImportersDW.Integration.Order_Staging the way Microsoft's SSIS package would,
-- so Integration.MigrateStagedOrderData has input to work on.
-- Run against WideWorldImportersDW. Needs the WideWorldImporters (shop) database on the same server.

SET NOCOUNT ON;

-- 1. Pick a time window: @WindowMonths long, ending @MonthsBack months before the warehouse's last load.
--    The default is the dev batch; jobs/order.json changes it for the holdout.
DECLARE @MonthsBack   int = 0;
DECLARE @WindowMonths int = 1;
DECLARE @LastLoad   datetime2(7) = (SELECT [Cutoff Time] FROM Integration.[ETL Cutoff] WHERE [Table Name] = N'Order');
DECLARE @NewCutoff  datetime2(7) = DATEADD(month, -@MonthsBack, @LastLoad);
DECLARE @LastCutoff datetime2(7) = DATEADD(month, -@WindowMonths, @NewCutoff);

-- 2. Clear staging (in-memory tables don't allow TRUNCATE)
DELETE FROM Integration.Order_Staging;

-- 3. Pull the rows from the shop database. In-memory tables can't be written in the same
--    statement as another user database, so go through a temp table.
CREATE TABLE #rows (
    [Order Date Key] date,
    [Picked Date Key] date,
    [WWI Order ID] int,
    [WWI Backorder ID] int,
    [Description] nvarchar(100),
    [Package] nvarchar(50),
    [Quantity] int,
    [Unit Price] decimal(18,2),
    [Tax Rate] decimal(18,3),
    [Total Excluding Tax] decimal(18,2),
    [Tax Amount] decimal(18,2),
    [Total Including Tax] decimal(18,2),
    [WWI City ID] int,
    [WWI Customer ID] int,
    [WWI Stock Item ID] int,
    [WWI Salesperson ID] int,
    [WWI Picker ID] int,
    [Last Modified When] datetime2(7)
);

INSERT INTO #rows
EXEC WideWorldImporters.Integration.GetOrderUpdates @LastCutoff = @LastCutoff, @NewCutoff = @NewCutoff;

INSERT INTO Integration.Order_Staging ([Order Date Key], [Picked Date Key], [WWI Order ID], [WWI Backorder ID], [Description], [Package], [Quantity], [Unit Price], [Tax Rate], [Total Excluding Tax], [Tax Amount], [Total Including Tax], [WWI City ID], [WWI Customer ID], [WWI Stock Item ID], [WWI Salesperson ID], [WWI Picker ID], [Last Modified When])
SELECT [Order Date Key], [Picked Date Key], [WWI Order ID], [WWI Backorder ID], [Description], [Package], [Quantity], [Unit Price], [Tax Rate], [Total Excluding Tax], [Tax Amount], [Total Including Tax], [WWI City ID], [WWI Customer ID], [WWI Stock Item ID], [WWI Salesperson ID], [WWI Picker ID], [Last Modified When]
FROM #rows;

DROP TABLE #rows;

-- 4. Open a lineage record. MigrateStagedOrderData looks for one with no completion time.
EXEC Integration.GetLineageKey @TableName = N'Order', @NewCutoffTime = @NewCutoff;

-- 5. Report what got staged
SELECT COUNT(*) AS staged_rows, @LastCutoff AS window_from, @NewCutoff AS window_to
FROM Integration.Order_Staging;
